# CELL 17: LOOK AT A FAMILY   (Eir 2.0.13)
# ============================================================================
# "Cr1 O3 Pr1  2 of 6 flagged" in the triage is interesting. Seeing the six is
# the next thing you want, and it is the point at which a pattern separates
# from an accident: if the two bad ones are from one paper and the four sound
# ones from four others, that is a different finding from two bad entries
# scattered through six independent determinations.
#
# DOES NOTHING UNLESS ASKED. Set SHOW_FAMILY and re-run.
#
# Matching is on the ELEMENT SET, not the formula string. Eir writes ICSD
# style - "Eu1 O3 V1", not "EuVO3" - and the non-stoichiometric variants are
# usually the ones worth seeing: asking for LaMnO3 should return
# La0.8Mn1O2.8 and La1Mn0.95O3.02 as well, because whether an entry is
# off-stoichiometry is a finding rather than a reason to exclude it.
#
# Selection when a family is larger than the limit: EVERY structure that
# failed something, then sound ones spread evenly across the GII range. The
# flagged ones are why you asked; the sound ones are the control, and taking
# the first few would give you whichever the filesystem listed first.

import re as _re

FAMILY_LIMIT = 20        # rows shown before the selection starts choosing


def _elements_of(text):
    """The element set in a formula, however it is written."""
    if text is None or text != text:
        return frozenset()
    return frozenset(_re.findall(r"[A-Z][a-z]?", str(text)))


def look_at_family(spec, dfq=None, limit=FAMILY_LIMIT, sort_by="gii"):
    """
    Every entry in this compositional family, flagged ones first.

    spec     "LaMnO3", "Cr1 O3 Pr1", "Eu V O" - anything from which element
             symbols can be read. Matching ignores stoichiometry, so the
             off-stoichiometry entries come too.
    limit    rows shown. Everything flagged is kept; the remainder of the
             budget goes to sound structures spread across the GII range.
    sort_by  "gii", "year" or "code"
    """
    _df = dfq if dfq is not None else globals().get("dfq")
    if _df is None:
        print("No results in memory. Run the post-processing cell first.")
        return None

    want = _elements_of(spec)
    if not want:
        print(f"Could not read any element symbols from {spec!r}.")
        return None

    per = (build_structure_table(_df) if "build_structure_table" in globals()
           else _df.drop_duplicates("filename"))
    per = per.copy()
    per["_els"] = per["chemical_formula"].map(_elements_of)
    hit = per[per["_els"] == want]
    if not len(hit):
        _near = per[per["_els"].map(lambda s: want <= s)]
        if len(_near):
            print(f"No entry with exactly {sorted(want)}. "
                  f"{len(_near)} contain those elements plus others:")
            for _f in sorted(_near["chemical_formula"].unique())[:8]:
                print(f"    {_f}")
        else:
            print(f"Nothing with elements {sorted(want)}.")
        return None

    # what counts as flagged
    # "Flagged" here means EXPUNGE or NOT_ASSESSED, OR a failed screen that
    # PGRM does not currently gate on. The radii-ratio and bond-valence
    # distance screens have no G code: they say a contact is short relative to
    # the ions rather than impossible, and whether that should expunge is an
    # open question. 25 perovskites fail only those two and are ACCEPT under
    # PGRM while the triage counts them as flagged, which is why a family can
    # read "1 flagged" here and "5 of 5" there. Counting them keeps the two
    # views consistent until the question is settled.
    _tier = hit.get("structure_pgrm_tier")
    _screen_fail = None
    for _c in ("structure_core_geometry_plausible",
               "structure_bvs_geometry_plausible"):
        if _c in hit.columns:
            _f = hit[_c].astype(str).str.lower().eq("false")
            _screen_fail = _f if _screen_fail is None else (_screen_fail | _f)
    if _tier is not None:
        _t = hit["structure_pgrm_tier"].isin(["EXPUNGE", "NOT_ASSESSED"])
        if _screen_fail is not None:
            _t = _t | _screen_fail
        bad = hit[_t]
        ok = hit[~hit.index.isin(bad.index)]
    elif "n_screens_failed" in hit.columns:
        _n = pd.to_numeric(hit["n_screens_failed"], errors="coerce").fillna(0)
        bad, ok = hit[_n > 0], hit[_n == 0]
    else:
        bad, ok = hit.iloc[0:0], hit

    # selection: all the bad, then sound ones spread across the GII range
    shown, note = hit, ""
    if len(hit) > limit:
        _room = max(0, limit - len(bad))
        if _room and len(ok) > _room:
            _o = ok.assign(_g=pd.to_numeric(ok.get("gii"), errors="coerce"))
            _o = _o.sort_values("_g")
            _idx = np.linspace(0, len(_o) - 1, _room).round().astype(int)
            ok_sel = _o.iloc[sorted(set(_idx))]
        else:
            ok_sel = ok.head(_room)
        shown = pd.concat([bad, ok_sel])
        note = (f"  showing {len(bad)} flagged and {len(ok_sel)} of {len(ok)} "
                f"sound, spread across the GII range. limit={limit}.")

    _by = {"gii": "gii", "year": "year", "code": "icsd_code"}.get(sort_by, "gii")
    if _by in shown.columns:
        shown = shown.sort_values(_by, ascending=(_by != "gii"),
                                  na_position="last")

    print("=" * 78)
    print(f"  {spec}   [{' '.join(sorted(want))}]   {len(hit)} entries, "
          f"{len(bad)} flagged")
    print("=" * 78)
    if note:
        print(note)
    print()
    _cols = [c for c in ("icsd_code", "chemical_formula", "year",
                         "structure_pgrm_tier", "structure_pgrm_reason",
                         "gii", "anion_anion_min", "cation_cation_min")
             if c in shown.columns]
    for _l in shown[_cols].to_string(index=False).splitlines():
        print("  " + _l)

    # the provenance question: is it one paper or many?
    if len(bad) >= 2 and "journal" in hit.columns:
        print()
        _bj = bad["journal"].fillna("?").value_counts()
        _aj = hit["journal"].fillna("?").nunique()
        print(f"  The {len(bad)} flagged entries come from "
              f"{len(_bj)} journal(s), out of {_aj} across the family:")
        for _j, _n in _bj.items():
            print(f"      {_n:3}  {str(_j)[:58]}")
        if len(_bj) == 1 and _aj > 1:
            print("  One source for every flagged entry. That is a pattern,")
            print("  not an accident: check the paper before the database.")
    if "year" in hit.columns and len(bad):
        _by_ = pd.to_numeric(bad["year"], errors="coerce").dropna()
        _ay = pd.to_numeric(hit["year"], errors="coerce").dropna()
        if len(_by_) and len(_ay):
            print()
            print(f"  flagged span {int(_by_.min())}-{int(_by_.max())};  "
                  f"family span {int(_ay.min())}-{int(_ay.max())}")
    print()
    print("  look_at(<code>) for any one of these.")
    print()
    return shown
